// From "send" to the first visible word of the reply on the phone. Time unit: milliseconds.
// Parameters are MEASURED values (9router request log, the Fate Simulator prompt): see specs/generation/README.md.
const int PREP = 540;            // building the prompt in the page (stage1 in generationInfo)
const int TTFT_MIN = 2500;       // router time to first token (3176, 5007, 4502, 4334 measured)
const int TTFT_MAX = 7000;
const int R = @R@;               // hidden reasoning tokens before the first visible word
const int RATE_MIN = 18;         // ms per token: about 46-55 tokens/s measured (86 s for 4640 tokens, 50 s for 2212)
const int RATE_MAX = 22;
const int LIMIT = @LIMIT@;       // the wait we want the user to have at most

clock t;                         // since the user pressed send
clock x;                         // per-token timer
int[0,6000] done = 0;            // reasoning tokens produced so far
